const dir=mkdtempSync(join(tmpdir(),'tracer-active-backup-')),database=join(dir,'active.sqlite'),destination=join(dir,'during-write.sqlite'),original=new DatabaseSync('projects/tracer/tracer.sqlite',{readOnly:true});await backup(original,database);original.close();
const repository=new SQLiteRepository(database),t=new Tracer(repository);let child;
function wait(predicate){return new Promise((resolve,reject)=>{const timer=setTimeout(()=>{child.off('message',listener);reject(Error('IPC timeout'));},10000);const listener=message=>{if(predicate(message)){clearTimeout(timer);child.off('message',listener);resolve(message);}};child.on('message',listener);});}
try{
 const before=await t.exportProject(),byKey=new Map(before.current.entities.map(e=>[e.key,e])),work=byKey.get('WORK-028'),requirement=byKey.get('REQ-036');
 const pair={beforeId:'96dd613d-1bb6-4d45-a661-4056b649eea6',afterId:'841b02ea-59d9-4839-a655-45fceabe5217'},verification={caseId:'0c7a9a41-0e55-4161-b058-5ff7b719045f',openingCommandId:'configuration-original-req035-verification-open-2026-10-28'},assessment={assessmentId:'4dc81851-217e-4e9b-95d4-4dd1e0d494af',openingCommandId:'configuration-original-final-assessment-open-2026-10-28'};
 const beforeComparison=await t.configurations.compare(pair),beforeVerification=await t.verification.analyze(verification),beforeAssessment=await t.changeAssessments.analyze(assessment);
 const command={commandId:'disposable-real-project-active-backup-confirmed-2026-10-28',expectedSchemaVersion:7,expectedProjectRevision:before.projectRevision,expectedEvidenceRevision:before.evidenceRevision,operations:[{op:'entity.update',id:work.id,expectedVersion:work.version,input:{fields:{...work.fields,title:work.fields.title+' (disposable backup probe)'}}}],receipt:{outputId:work.id,expectedOutputVersion:work.version+1,outcome:'Synthetic backup concurrency proof on faithful disposable real-project copy; not engineering verification of REQ-036.',inputs:[{entityId:requirement.id,fields:['statement'],role:'declared probe scope'}]}};
