 const restoredRepository=new SQLiteRepository(destination),restored=new Tracer(restoredRepository);try{assert.deepEqual(await restored.exportProject(),before);assert.equal(await restored.evaluations.getOutcome(command.commandId),null);assert.deepEqual(await restored.configurations.compare(pair),beforeComparison);assert.deepEqual(await restored.verification.analyze(verification),beforeVerification);assert.deepEqual(await restored.changeAssessments.analyze(assessment),beforeAssessment);}finally{restoredRepository.close();}
 child.send({action:'release'});const committed=await result;assert.equal(committed.error,undefined);assert.deepEqual(await t.evaluations.getOutcome(command.commandId),committed.result);assert.equal((await t.getEntity(work.id)).version,work.version+1);assert.deepEqual(await t.configurations.compare(pair),beforeComparison);
