import{fork}from'node:child_process';import{once}from'node:events';import{mkdtempSync,rmSync,writeFileSync,readFileSync}from'node:fs';import{tmpdir}from'node:os';import{join,resolve}from'node:path';import{DatabaseSync,backup}from'node:sqlite';import{createHash}from'node:crypto';import assert from'node:assert/strict';import prettier from'prettier';import{Tracer}from'../../src/index.ts';import{SQLiteRepository}from'../../src/persistence/sqlite.ts';
const actor={actor:'concurrent-application-proof',reason:'Explicit reopen on disposable configured-research copy only'},children=[];
function wait(child,predicate){return new Promise((resolve,reject)=>{const timer=setTimeout(()=>{child.off('message',listener);reject(Error('worker timeout'));},10000);const listener=m=>{if(predicate(m)){clearTimeout(timer);child.off('message',listener);resolve(m);}};child.on('message',listener);});}
async function worker(database){const child=fork(resolve('output/concurrent-local/workload-worker.mjs'),[database],{stdio:['ignore','ignore','inherit','ipc']});children.push(child);await wait(child,m=>m.ready);return{request(method,input){const result=wait(child,m=>m.id===1);child.send({id:1,method,args:[input,actor]});return result;}};}
const verification={caseId:'9bf0678d-b58b-4c37-8ab4-bffc600cf55c',openingCommandId:'7a664ff8-b146-4495-8b79-4066bfc6a02f'},assessment={assessmentId:'fb1cb23b-1de6-4554-b98f-1ee0f48ad25f',openingCommandId:'e9efcb31-98f9-4dba-8152-ea26b49a7df1'},pair={beforeId:'6fdd7faf-2bc9-447f-8ac0-acce5c5d8ccf',afterId:'4a81ef31-763f-4f5d-8ea4-bb74f0a07f51'},results=[];
async function proposal(t,kind,commandId){if(kind==='verification'){const a=await t.verification.analyze(verification);return{...verification,commandId,expectedCaseVersion:a.view.case.version,expectedSchemaVersion:a.view.model.context.schemaVersion,expectedProjectRevision:a.view.model.context.projectRevision,expectedEvidenceRevision:a.view.model.context.evidenceRevision,expectedAnalysisDigest:a.proposalDigest,reason:actor.reason};}const view=await t.changeAssessments.get(assessment);return{...assessment,commandId,expectedAssessmentVersion:view.assessment.version,expectedSchemaVersion:view.model.context.schemaVersion,expectedProjectRevision:view.model.context.projectRevision,expectedEvidenceRevision:view.model.context.evidenceRevision,reason:actor.reason};}
for(const kinds of[['verification','assessment'],['verification','verification'],['assessment','assessment']]){
 const dir=mkdtempSync(join(tmpdir(),'tracer-app-race-')),database=join(dir,'copy.sqlite'),source=new DatabaseSync('projects/tracer/backups/research-configuration-change-complete.sqlite',{readOnly:true});await backup(source,database);source.close();const r=new SQLiteRepository(database),t=new Tracer(r),group=children.length;
 try{
  const before=await t.exportProject(),comparison=await t.configurations.compare(pair),inputs=await Promise.all(kinds.map((kind,i)=>proposal(t,kind,`concurrent-${kinds.join('-')}-${i}`))),workers=await Promise.all([worker(database),worker(database)]),methods=kinds.map(kind=>kind==='verification'?'verification.reopen':'changeAssessments.reopen');
  writeFileSync(`output/concurrent-local/research-race-${kinds.join('-')}-intent.json`,JSON.stringify({inputs,methods,actor},null,2)+'\n',{flag:'wx'});
  const responses=await Promise.all(workers.map((w,i)=>w.request(methods[i],inputs[i]))),successful=responses.filter(x=>!x.error);assert.equal(successful.length,1);const winner=responses.findIndex(x=>!x.error),loser=1-winner;assert.ok(['busy','conflict'].includes(responses[loser].error.code));assert.deepEqual(await t.evaluations.getOutcome(inputs[winner].commandId),responses[winner].result);assert.equal(await t.evaluations.getOutcome(inputs[loser].commandId),null);
  const interim=await t.exportProject();assert.equal(interim.projectRevision,before.projectRevision+1);assert.equal(interim.evidence.receipts.length,before.evidence.receipts.length+1);assert.deepEqual(await t.configurations.compare(pair),comparison);
  for(const key of['changesets','revisions'])assert.deepEqual(interim.provenance[key].slice(0,before.provenance[key].length),before.provenance[key]);for(const key of Object.keys(before.evidence))assert.deepEqual(interim.evidence[key].slice(0,before.evidence[key].length),before.evidence[key]);
  // Reprepare the rejected operation deliberately against the newly read context, under a NEW identity.
  let freshResult=null;if(kinds[loser]!==kinds[winner]){const fresh=await proposal(t,kinds[loser],inputs[loser].commandId+'-explicit-adoption');freshResult=await t[kinds[loser]==='verification'?'verification':'changeAssessments'].reopen(fresh,actor);assert.deepEqual(await t.evaluations.getOutcome(fresh.commandId),freshResult);assert.deepEqual(await t.configurations.compare(pair),comparison);}
  results.push({operations:methods,inputs,responses:responses.map(x=>({error:x.error??null,durationMs:x.durationMs??null,commandId:x.result?.commandId??null,receiptId:x.result?.receipt.id??null})),acknowledged:1,rejectedWithoutOutcome:true,nativeRevisionBefore:before.projectRevision,nativeRevisionAfterRace:interim.projectRevision,receiptDelta:1,originalHistoryEvidencePreserved:true,fixedPairComparisonUnchanged:true,explicitlyRepreparedDifferentApplication:freshResult?.commandId??null});
 }finally{for(const child of children.slice(group)){const exited=once(child,'exit');child.kill();await exited;}r.close();rmSync(dir,{recursive:true,force:true});}
}
const report={date:'2026-10-28',scope:'Independent OS processes issue simultaneous controlled reopen requests against exact guarded retained configured-research contexts on three disposable online copies. No live state changed.',candidateHashes:['src/persistence/sqlite.ts','src/application/verification.ts','src/application/change-assessments.ts','output/concurrent-local/workload-worker.mjs'].map(path=>({path,sha256:createHash('sha256').update(readFileSync(path)).digest('hex')})),results,limitations:'Simultaneous independent process requests, not an instrumented held-lock application barrier. Reopen races only; disposition/action/result selection and changed-basis races remain separate acceptance work. Explicit reprepare uses a new identity; no uncertain command was blindly replayed.'};writeFileSync('projects/tracer/concurrent-local-research-races.json',await prettier.format(JSON.stringify(report),{...await prettier.resolveConfig('projects/tracer/concurrent-local-research-races.json'),parser:'json'}),{flag:'wx'});console.log(JSON.stringify(results.map(x=>({operations:x.operations,outcomes:x.responses.map(y=>y.error?.code??'success'),fixedPairComparisonUnchanged:x.fixedPairComparisonUnchanged}))));

