const directory=mkdtempSync(join(tmpdir(),'tracer-http-proof-')),database=join(directory,'project.sqlite'),source=new DatabaseSync('projects/tracer/tracer.sqlite',{readOnly:true});await backup(source,database);source.close();const children=[];
async function open(){const child=fork(resolve('output/concurrent-local/http-worker.mjs'),[database],{stdio:['ignore','ignore','inherit','ipc']});children.push(child);const ready=await new Promise((resolve,reject)=>{const timer=setTimeout(()=>reject(Error('HTTP worker timeout')),10000);child.once('message',m=>{clearTimeout(timer);resolve(m);});});return{child,origin:ready.origin};}
